import React, {type CSSProperties} from 'react';
import clsx from 'clsx';
// Generated by plugins/icons.mjs from the icons the content uses.
import icons from '@site/src/generated/icons.json';

type IconData = {width: number; height: number; path: string[]};
const ICONS = icons as Record<string, IconData>;

export type IconProps = {
  icon: string;
  color?: string;
  size?: number | string;
  className?: string;
  style?: CSSProperties;
};

/** Font Awesome icon by Fern-style name, e.g. "fa-solid fa-rocket" or "rocket". */
export default function Icon({icon, color, size, className, style}: IconProps): React.JSX.Element | null {
  const data = ICONS[icon?.trim?.()];
  if (!data) return null;
  const dimension = typeof size === 'number' ? `${size / 4}rem` : size;
  return (
    <svg
      className={clsx('fern-icon', className)}
      viewBox={`0 0 ${data.width} ${data.height}`}
      aria-hidden="true"
      focusable="false"
      role="img"
      style={{color, ...(dimension ? {width: dimension, height: dimension} : {}), ...style}}>
      {data.path.map((d, i) => (
        <path key={i} fill="currentColor" d={d} opacity={data.path.length > 1 && i === 0 ? 0.4 : 1} />
      ))}
    </svg>
  );
}
